syntax:
std::unique_ptr<T> ptr = std::make_unique<T>(constructor_args); // for exclusive ownership
std::shared_ptr<T> ptr = std::make_shared<T>(constructor_args); // for shared ownership
// Usage: pointer->member or *pointer
// Smart pointers automatically delete managed object when no longer needed

code_example:
#include <iostream>
#include <memory>

class Widget {
public:
    Widget() { std::cout << "Widget constructed" << std::endl; }
    ~Widget() { std::cout << "Widget destroyed" << std::endl; }
    void do_something() { std::cout << "Doing something" << std::endl; }
};

int main() {
    auto ptr1 = std::make_unique<Widget>(); // unique ownership
    ptr1->do_something();
    // shared ownership example
    std::shared_ptr<Widget> ptr2 = std::make_shared<Widget>();
    std::shared_ptr<Widget> ptr3 = ptr2; // shared ownership
    ptr2->do_something();
    // No need to delete; destructors are called automatically
    return 0;
}
